function validate([xCoord, yCoord]) {
  if (xCoord.length !== yCoord.length) return 'xCoord and yCoord must have the same length.';
  if (xCoord.length < 1 || xCoord.length > 200000) return 'There must be 1 to 200,000 points.';
  const seen = new Set();
  for (let i = 0; i < xCoord.length; i++) {
    const x = xCoord[i], y = yCoord[i];
    if (x < 0 || y < 0 || x > 80000000 || y > 80000000) return 'Each coordinate is between 0 and 80,000,000.';
    if (seen.has(x + ',' + y)) return 'All points must be different.';
    seen.add(x + ',' + y);
  }
  return null;
}

