function maxRectangleArea(xCoord, yCoord) {
  const points = xCoord.map((x, i) => [x, yCoord[i]]);
  points.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const ys = [...new Set(yCoord)].sort((a, b) => a - b);
  const rank = new Map(ys.map((y, i) => [y, i + 1]));
  const tree = new Array(ys.length + 1).fill(0);
  const add = (i) => {
    while (i < tree.length) {
      tree[i] += 1;
      i += i & -i;
    }
  };
  const countUpTo = (i) => {
    let total = 0;
    while (i > 0) {
      total += tree[i];
      i -= i & -i;
    }
    return total;
  };
  const lastSeen = new Map();
  let best = -1;
  let start = 0;
  while (start < points.length) {
    const x = points[start][0];
    let end = start;
    while (end < points.length && points[end][0] === x) end++;
    for (let k = start; k < end; k++) add(rank.get(points[k][1]));
    for (let k = start; k + 1 < end; k++) {
      const low = points[k][1];
      const high = points[k + 1][1];
      const count = countUpTo(rank.get(high)) - countUpTo(rank.get(low) - 1);
      const key = low + ',' + high;
      const prev = lastSeen.get(key);
      if (prev !== undefined && count - prev.count === 2) {
        best = Math.max(best, (x - prev.x) * (high - low));
      }
      lastSeen.set(key, { x, count });
    }
    start = end;
  }
  return best;
}

