function maxRectangleArea(xCoord, yCoord) {
  const n = xCoord.length;
  let best = -1;
  // Try every pair of points as the bottom-left and top-right corners.
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const x1 = xCoord[i], y1 = yCoord[i], x2 = xCoord[j], y2 = yCoord[j];
      if (x1 >= x2 || y1 >= y2) continue;
      let corners = 0, blocked = false;
      for (let k = 0; k < n; k++) {
        const x = xCoord[k], y = yCoord[k];
        if (x < x1 || x > x2 || y < y1 || y > y2) continue;
        if ((x === x1 || x === x2) && (y === y1 || y === y2)) corners++;
        else blocked = true;
      }
      if (corners === 4 && !blocked) best = Math.max(best, (x2 - x1) * (y2 - y1));
    }
  }
  return best;
}

