function generate(rand, size) {
  const large = size === 'large';
  // Points sit on a few vertical and horizontal lines, so rectangles and blocking points are common.
  const lines = large ? 45 + Math.floor(rand() * 40) : 2 + Math.floor(rand() * 4);
  const spread = large ? 80000000 : 10;
  const coordinates = () => {
    const values = new Set();
    while (values.size < lines) values.add(Math.floor(rand() * (spread + 1)));
    return [...values];
  };
  const columns = coordinates(), rows = coordinates();
  const n = large ? 2000 : rand() < 0.1 ? 1 : Math.min(12, Math.ceil(lines * lines * (0.4 + 0.6 * rand())));
  const used = new Set(), xCoord = [], yCoord = [];
  while (xCoord.length < n) {
    const x = columns[Math.floor(rand() * lines)], y = rows[Math.floor(rand() * lines)];
    if (used.has(x + ',' + y)) continue;
    used.add(x + ',' + y);
    xCoord.push(x);
    yCoord.push(y);
  }
  return [xCoord, yCoord];
}
